/**
 * native-rules — push whisper native rules (map_remote / map_local(file)) into
 * whistle's own rule store via its CGI, and keep them in sync.
 *
 * Why direct CGI instead of the plugin's rulesServer hook:
 * older whistle versions called the plugin `rulesServer` hook for every request
 * matching `pattern whistle.pbmockx://`, but whistle 2.10.x no longer invokes
 * plugin rulesServer for ordinary HTTP traffic (it only fires for websocket /
 * tunnel / explicit plugin-protocol requests). As a result the `map_remote` and
 * `map_local(file)` rules generated by `RuleEngine.toWhistleRules()` were never
 * handed to whistle and silently had no effect.
 *
 * The workaround is to inject that same rule text straight into whistle's rule
 * library through its own CGI (`/cgi-bin/rules/add`) under a dedicated file name,
 * and to remove/refresh it as pbmockx rules change. See `syncNativeRules` /
 * `clearNativeRules`.
 */

import * as http from 'http';
import { rules } from './ctx';

/** Name of the whistle rule file that holds pbmockx-generated native rules. */
export const NATIVE_RULES_FILE = 'pbmockx-native';

export interface NativeSyncResult { ok: boolean; synced?: boolean; error?: string; }

/** Coerce a port-ish value to a usable number, else undefined. */
function parsePort(v: any): number | undefined {
  if (v === undefined || v === null || v === '') return undefined;
  const n = Number(v);
  return Number.isFinite(n) && n > 0 ? n : undefined;
}

/**
 * Resolve the whistle web port. Priority:
 *   env PBMOCKX_WHISTLE_PORT → env WHISTLE_PORT → options.config.uiport
 *   → options.config.port → 8899
 */
export function whistlePort(options?: any): number {
  const cfg = options && options.config;
  return (
    parsePort(process.env.PBMOCKX_WHISTLE_PORT) ??
    parsePort(process.env.WHISTLE_PORT) ??
    parsePort(cfg && cfg.uiport) ??
    parsePort(cfg && cfg.port) ??
    8899
  );
}

/** POST a JSON body to a whistle CGI path. Resolves the parsed JSON reply. */
function postCgi(port: number, apiPath: string, body: any): Promise<any> {
  return new Promise((resolve, reject) => {
    const data = JSON.stringify(body);
    const req = http.request({
      hostname: '127.0.0.1',
      port,
      path: apiPath,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(data),
      },
    }, (res) => {
      const chunks: Buffer[] = [];
      res.on('data', (c) => chunks.push(c));
      res.on('end', () => {
        const raw = Buffer.concat(chunks).toString('utf-8');
        if (!res.statusCode || res.statusCode < 200 || res.statusCode >= 300) {
          reject(new Error(`HTTP ${res.statusCode}: ${raw.slice(0, 200)}`));
          return;
        }
        try { resolve(JSON.parse(raw)); }
        catch { reject(new Error(`invalid JSON response: ${raw.slice(0, 200)}`)); }
      });
    });
    req.on('error', reject);
    req.setTimeout(3000, () => req.destroy(new Error('timeout')));
    req.write(data);
    req.end();
  });
}

/** Whether a CGI reply signals success (`ec === 0`). */
function isOk(resp: any): boolean {
  return !!resp && resp.ec === 0;
}

/** Human-readable reason from a CGI reply. */
function cgiError(resp: any): string {
  if (!resp) return 'empty response';
  const msg = resp.errmsg || resp.error || resp.msg;
  if (msg) return String(msg);
  try { return JSON.stringify(resp).slice(0, 200); } catch { return 'unknown error'; }
}

/** Whether a "remove" failure actually just means the file was already absent. */
function removeOk(resp: any): boolean {
  if (isOk(resp)) return true;
  const msg = (resp && (resp.errmsg || resp.error || resp.msg)) || '';
  return /not\s*found|no\s*such|does\s*not\s*exist|不存在/i.test(String(msg));
}

function errMessage(e: any): string {
  return e && e.message ? e.message : String(e);
}

/**
 * Push the current map_remote / map_local(file) rules into whistle's rule store.
 * Empty rule text degrades to `clearNativeRules` (so stale rules never linger).
 * Never throws — all failures are returned as `{ ok: false, error }`.
 */
export async function syncNativeRules(options?: any): Promise<NativeSyncResult> {
  if (process.env.PBMOCKX_DISABLE_NATIVE_SYNC === '1') return { ok: true, synced: false };

  const text = rules.toWhistleRules().join('\n');
  if (!text.trim()) return clearNativeRules(options);

  try {
    const resp = await postCgi(whistlePort(options), '/cgi-bin/rules/add', {
      name: NATIVE_RULES_FILE,
      value: text,
      // `selected: true` is required — without it whistle stores the rule file
      // but does not enable it.
      selected: true,
    });
    if (isOk(resp)) return { ok: true, synced: true };
    return { ok: false, error: cgiError(resp) };
  } catch (e) {
    return { ok: false, error: errMessage(e) };
  }
}

/**
 * Remove the pbmockx-native rule file from whistle. Idempotent: a missing file
 * is treated as success. Never throws.
 */
export async function clearNativeRules(options?: any): Promise<NativeSyncResult> {
  if (process.env.PBMOCKX_DISABLE_NATIVE_SYNC === '1') return { ok: true, synced: false };

  try {
    const resp = await postCgi(whistlePort(options), '/cgi-bin/rules/remove', {
      name: NATIVE_RULES_FILE,
    });
    if (removeOk(resp)) return { ok: true, synced: true };
    return { ok: false, error: cgiError(resp) };
  } catch (e) {
    return { ok: false, error: errMessage(e) };
  }
}
